  IF (SELECT resumen FROM public.reglas WHERE id = 'discovery.barrido') IS DISTINCT FROM $v$Territorio limpio: ni insistir ni rendirse, cambiar de territorio. Insistir en zona sana te vuelve interrogador; rendirte regala la visita. LA PRUEBA: cuando el cliente dijo con claridad que en un territorio no tiene problema, ¿el vendedor siguió preguntando ahí, más y más, en vez de cambiar de territorio? Si siguió ahí, falla. No se cuentan territorios: si el dolor salió en el primero, quedarse ahí es lo correcto.$v$ THEN RAISE EXCEPTION 'la regla discovery.barrido no quedó'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.reglas r WHERE r.id = 'discovery.barrido' AND EXISTS (SELECT 1 FROM public.doctrina d WHERE d.is_active AND strpos(d.body, r.cita_cerebro) > 0)) THEN RAISE EXCEPTION 'la cita de discovery.barrido no está en el Cerebro'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'discovery.bordes_restriccion') IS DISTINCT FROM $v$Casi toda restricción tiene bordes: qué cubre, qué queda fuera, hasta cuándo dura. LA PRUEBA: cuando el cliente dijo que no puede comprar por un contrato, una política o una circunstancia, ¿el vendedor hizo una o dos preguntas para saber qué cubre y qué queda fuera, en vez de tomarlo como total? Averiguar rápido no es quedarse a platicar.$v$ THEN RAISE EXCEPTION 'la regla discovery.bordes_restriccion no quedó'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.reglas r WHERE r.id = 'discovery.bordes_restriccion' AND EXISTS (SELECT 1 FROM public.doctrina d WHERE d.is_active AND strpos(d.body, r.cita_cerebro) > 0)) THEN RAISE EXCEPTION 'la cita de discovery.bordes_restriccion no está en el Cerebro'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'discovery.confirmacion_con_sus_palabras') IS DISTINCT FROM $v$El dolor que el cliente contó se aprende con SUS palabras y se usa en la presentación: «como me dijo que se le acaba en temporada, mire lo que le traigo». En el descubrimiento devolverlo no es obligatorio: se puede quedar callado y seguir. LA PRUEBA: al presentar, ¿el vendedor conecta su propuesta con el dolor que el cliente contó, usando las palabras del cliente? Si el cliente no contó ningún dolor, el criterio es no_aplica.$v$ THEN RAISE EXCEPTION 'la regla discovery.confirmacion_con_sus_palabras no quedó'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.reglas r WHERE r.id = 'discovery.confirmacion_con_sus_palabras' AND EXISTS (SELECT 1 FROM public.doctrina d WHERE d.is_active AND strpos(d.body, r.cita_cerebro) > 0)) THEN RAISE EXCEPTION 'la cita de discovery.confirmacion_con_sus_palabras no está en el Cerebro'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'discovery.dolor_directo') IS DISTINCT FROM $v$El dolor nunca se pregunta directo: «¿qué problemas tiene?» produce «ninguno», garantizado. Se deja emerger. LA PRUEBA: ¿el vendedor preguntó por problemas en general —«¿qué problemas tiene?», «¿algo que le falle?», «¿algo que no le guste?»—? Con una basta. Preguntar por una situación concreta («¿le ha tocado quedarse sin su producto estrella?») no es esto: es la pregunta específica.$v$ THEN RAISE EXCEPTION 'la regla discovery.dolor_directo no quedó'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.reglas r WHERE r.id = 'discovery.dolor_directo' AND EXISTS (SELECT 1 FROM public.doctrina d WHERE d.is_active AND strpos(d.body, r.cita_cerebro) > 0)) THEN RAISE EXCEPTION 'la cita de discovery.dolor_directo no está en el Cerebro'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'discovery.escalera_capas') IS DISTINCT FROM $v$La escalera de capas: capa 1 los hechos, capa 2 la puerta (el cliente suelta una pista o cierra con un «bien»), capa 3 el dolor, que solo se abre si recoges la pista y profundizas. LA PRUEBA: ¿el vendedor pasó de los hechos a preguntas que abren la puerta y, cuando apareció una pista (el «aunque», el «a veces», el «lo único es que»), se quedó en ella y la excavó hasta que el cliente contó el dolor? No se cuentan territorios: si el dolor sale en el primero, se excava ahí y cumple. Devolverle el dolor con sus palabras no se pide aquí: se puede quedar callado y seguir. Si nunca apareció una pista, ¿por lo menos subió de los hechos a preguntas de capa 2? Entonces cumple lo que se podía.$v$ THEN RAISE EXCEPTION 'la regla discovery.escalera_capas no quedó'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.reglas r WHERE r.id = 'discovery.escalera_capas' AND EXISTS (SELECT 1 FROM public.doctrina d WHERE d.is_active AND strpos(d.body, r.cita_cerebro) > 0)) THEN RAISE EXCEPTION 'la cita de discovery.escalera_capas no está en el Cerebro'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'discovery.fabrica_dolor') IS DISTINCT FROM $v$Afirmar un problema que el cliente ya negó o del que no hay ningún indicio. Leer un dolor probable no es inventarlo. LA PRUEBA: después de que el cliente negó con claridad un problema, ¿el vendedor insiste en que sí lo tiene? O ¿afirma un problema sin nada que lo apoye —ni algo que dijo, ni algo que se ve, ni su giro—? Mencionar que a otros clientes les pasa no es esto: es normalizar.$v$ THEN RAISE EXCEPTION 'la regla discovery.fabrica_dolor no quedó'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.reglas r WHERE r.id = 'discovery.fabrica_dolor' AND EXISTS (SELECT 1 FROM public.doctrina d WHERE d.is_active AND strpos(d.body, r.cita_cerebro) > 0)) THEN RAISE EXCEPTION 'la cita de discovery.fabrica_dolor no está en el Cerebro'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'discovery.hueco') IS DISTINCT FROM $v$El hueco es algo que el cliente podría comprarte y no te compra: una familia que le compra a otro proveedor, una que le piden y no maneja, o una que no maneja nadie. No tiene señal verbal: se ve o se pregunta. Tiene que tener base: lo viste, te lo dijo, lo sabes por su giro o por negocios como el suyo. En la práctica lo que se ve se imagina. LA PRUEBA, en orden. (1) Al terminar la plática, ¿quedó al descubierto al menos un hueco concreto —una familia con nombre— porque el vendedor lo preguntó, lo vio, lo ancló en negocios como el suyo, o el cliente lo dijo? Si sí, cumple, aunque el vendedor no lo mencione: el hueco se descubre y se apunta para usarlo en la presentación. Preguntar no basta si la respuesta no dejó ninguna familia concreta. Ofrecérselo o decirle por qué le conviene no se pide aquí: eso es presentar el hueco (paso 4). (2) Si no apareció ninguno: ¿el vendedor buscó de verdad, o salió después de dos «no» seguidos? Entonces el criterio es no_aplica: hoy no había nada que descubrir. Buscó de verdad si usó al menos una de las herramientas del hueco —leer el lugar (ver o preguntar qué otras líneas maneja y con quién), preguntar qué le piden que no tenga, o anclar en negocios como el suyo— y, cada vez que la respuesta fue vaga, siguió con opciones concretas o con otra herramienta. Una respuesta es vaga si no dice qué ni con quién («de todo un poco», «lo normal»); si lo dice, o dice que no hay, ya contestó: no pide seguir. (3) Solo si no apareció ninguno y el vendedor no buscó de verdad, es no_cumple.$v$ THEN RAISE EXCEPTION 'la regla discovery.hueco no quedó'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.reglas r WHERE r.id = 'discovery.hueco' AND EXISTS (SELECT 1 FROM public.doctrina d WHERE d.is_active AND strpos(d.body, r.cita_cerebro) > 0)) THEN RAISE EXCEPTION 'la cita de discovery.hueco no está en el Cerebro'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'discovery.hueco_inventado') IS DISTINCT FROM $v$Fabricar un hueco: venderle un problema que no tiene. LA PRUEBA: ¿el vendedor afirma que al cliente le falta algo o que lo necesita sin ninguna base —ni lo dijo el cliente, ni se ve, ni es de su giro, ni lo apoya en negocios como el suyo—, o contradice lo que el cliente ya dijo? Preguntar nunca es inventar. Apoyarse en otros clientes como él, o decir lo que ve (en la práctica se imagina), tampoco.$v$ THEN RAISE EXCEPTION 'la regla discovery.hueco_inventado no quedó'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.reglas r WHERE r.id = 'discovery.hueco_inventado' AND EXISTS (SELECT 1 FROM public.doctrina d WHERE d.is_active AND strpos(d.body, r.cita_cerebro) > 0)) THEN RAISE EXCEPTION 'la cita de discovery.hueco_inventado no está en el Cerebro'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'discovery.interrogatorio') IS DISTINCT FROM $v$Interrogatorio: preguntas una tras otra que no recogen nada de lo que el cliente acaba de contestar. El cliente se siente en una entrevista, no en una plática. LA PRUEBA: ¿hay dos o más turnos seguidos en los que la pregunta del vendedor no recoge nada de la respuesta anterior del cliente? Dar opciones después de preguntar no es esto. Varias preguntas en un mismo turno son monólogo, no esto: no se cobra dos veces.$v$ THEN RAISE EXCEPTION 'la regla discovery.interrogatorio no quedó'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.reglas r WHERE r.id = 'discovery.interrogatorio' AND EXISTS (SELECT 1 FROM public.doctrina d WHERE d.is_active AND strpos(d.body, r.cita_cerebro) > 0)) THEN RAISE EXCEPTION 'la cita de discovery.interrogatorio no está en el Cerebro'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'discovery.lectura_falsa') IS DISTINCT FROM $v$Reconocer un estado que el cliente no mostró: leer es leer, no suponer. LA PRUEBA: ¿el vendedor le atribuye al cliente un estado (prisa, molestia, preocupación) que nada de lo que dijo o mostró indica, o que contradice lo que mostró?$v$ THEN RAISE EXCEPTION 'la regla discovery.lectura_falsa no quedó'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.reglas r WHERE r.id = 'discovery.lectura_falsa' AND EXISTS (SELECT 1 FROM public.doctrina d WHERE d.is_active AND strpos(d.body, r.cita_cerebro) > 0)) THEN RAISE EXCEPTION 'la cita de discovery.lectura_falsa no está en el Cerebro'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'discovery.lee_el_lugar') IS DISTINCT FROM $v$Lo que ves dice qué maneja y de quién: un producto de otra marca es un espacio ocupado; un estante vacío es una familia que nadie cubre. LA PRUEBA: ¿el vendedor averiguó, de al menos una familia distinta a lo que hoy le vende, si el cliente la maneja y con quién —viéndolo o preguntándolo—? Cuenta aunque la familia la nombre el cliente al contestar una pregunta abierta. En la práctica lo que se ve se imagina. Preguntar solo por lo que ya le vende no cumple.$v$ THEN RAISE EXCEPTION 'la regla discovery.lee_el_lugar no quedó'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.reglas r WHERE r.id = 'discovery.lee_el_lugar' AND EXISTS (SELECT 1 FROM public.doctrina d WHERE d.is_active AND strpos(d.body, r.cita_cerebro) > 0)) THEN RAISE EXCEPTION 'la cita de discovery.lee_el_lugar no está en el Cerebro'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'discovery.opinion_de_precio') IS DISTINCT FROM $v$Pedirle al cliente su opinión o su aprobación sobre los precios: te creas una objeción que no existía, cedes la autoridad sobre el precio y desperdicias tu ventaja de conocer el mercado. LA PRUEBA: ¿el vendedor le pregunta qué opina de los precios —«¿cómo ve los precios?», «¿siente algo muy caro?», «¿le parece que estamos bien de precio?»—? Preguntar hechos —a cómo compra, cada cuánto le suben, qué plazo le dan— no es esto.$v$ THEN RAISE EXCEPTION 'la regla discovery.opinion_de_precio no quedó'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.reglas r WHERE r.id = 'discovery.opinion_de_precio' AND EXISTS (SELECT 1 FROM public.doctrina d WHERE d.is_active AND strpos(d.body, r.cita_cerebro) > 0)) THEN RAISE EXCEPTION 'la cita de discovery.opinion_de_precio no está en el Cerebro'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'discovery.pregunta_especifica') IS DISTINCT FROM $v$El «bien» no es información: es un reflejo social. Para pasar de capa se pregunta por algo concreto que el cliente tenga que ir a buscar en su experiencia, o se normaliza citando a otros («varios clientes me comentan que batallan con faltantes, ¿a usted le pasa?»). LA PRUEBA: al subir a la capa 2, ¿el vendedor preguntó por un dato o una situación concreta —o normalizó citando a otros—, en vez de pedir una opinión general («¿qué tal le va?», «¿todo bien?»)? Y si recibió un «bien», ¿lo volvió a intentar con algo concreto en vez de conformarse?$v$ THEN RAISE EXCEPTION 'la regla discovery.pregunta_especifica no quedó'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.reglas r WHERE r.id = 'discovery.pregunta_especifica' AND EXISTS (SELECT 1 FROM public.doctrina d WHERE d.is_active AND strpos(d.body, r.cita_cerebro) > 0)) THEN RAISE EXCEPTION 'la cita de discovery.pregunta_especifica no está en el Cerebro'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'discovery.presiona_compromiso') IS DISTINCT FROM $v$Insistir en lo que el cliente ya dijo que está dentro de su compromiso es pedirle que rompa su palabra, y eso quema la relación. Se busca lo que sí puede, nunca se pelea lo que no. LA PRUEBA: después de que el cliente dijo que algo está dentro de su compromiso, ¿el vendedor insiste en venderle eso mismo?$v$ THEN RAISE EXCEPTION 'la regla discovery.presiona_compromiso no quedó'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.reglas r WHERE r.id = 'discovery.presiona_compromiso' AND EXISTS (SELECT 1 FROM public.doctrina d WHERE d.is_active AND strpos(d.body, r.cita_cerebro) > 0)) THEN RAISE EXCEPTION 'la cita de discovery.presiona_compromiso no está en el Cerebro'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'discovery.qtqp') IS DISTINCT FROM $v$Quality Time with Quality People: tu tiempo de trabajo es para quien puede comprar. Con quien hoy no puede, sé amable, deja la puerta abierta y sigue. LA PRUEBA: después de saber que hoy el cliente no puede comprar nada, ¿el vendedor se queda platicando de más —turno tras turno— en vez de despedirse bien? Dejar la puerta abierta o pedir un referido no es quedarse de más.$v$ THEN RAISE EXCEPTION 'la regla discovery.qtqp no quedó'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.reglas r WHERE r.id = 'discovery.qtqp' AND EXISTS (SELECT 1 FROM public.doctrina d WHERE d.is_active AND strpos(d.body, r.cita_cerebro) > 0)) THEN RAISE EXCEPTION 'la cita de discovery.qtqp no está en el Cerebro'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'discovery.receta_sin_diagnostico') IS DISTINCT FROM $v$Presentar antes de terminar el diagnóstico: en cuanto presentas, el cliente deja de revelar. Primero el examen, luego la receta. LA PRUEBA: durante el descubrimiento, ¿el vendedor habla de su producto, de sus beneficios, de su precio o de una promoción, o se lo ofrece como solución? Nombrar una familia para preguntar si la maneja («¿y el anticongelante, lo maneja?») no es recetar: es buscar. Tampoco anclar en negocios como el suyo.$v$ THEN RAISE EXCEPTION 'la regla discovery.receta_sin_diagnostico no quedó'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.reglas r WHERE r.id = 'discovery.receta_sin_diagnostico' AND EXISTS (SELECT 1 FROM public.doctrina d WHERE d.is_active AND strpos(d.body, r.cita_cerebro) > 0)) THEN RAISE EXCEPTION 'la cita de discovery.receta_sin_diagnostico no está en el Cerebro'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'discovery.rojo_insistir') IS DISTINCT FROM $v$Quedarse con un rojo: el tiempo que le das se lo quitas al siguiente cliente. LA PRUEBA: después de saber que hoy el cliente no puede o no quiere comprar nada —porque lo dijo o porque es grosero—, ¿el vendedor sigue tratando de convencerlo: le presenta, le argumenta, le ofrece o le pide que lo pruebe? Preguntar la razón no es insistir: es averiguar. Dejar la puerta abierta tampoco.$v$ THEN RAISE EXCEPTION 'la regla discovery.rojo_insistir no quedó'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.reglas r WHERE r.id = 'discovery.rojo_insistir' AND EXISTS (SELECT 1 FROM public.doctrina d WHERE d.is_active AND strpos(d.body, r.cita_cerebro) > 0)) THEN RAISE EXCEPTION 'la cita de discovery.rojo_insistir no está en el Cerebro'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'discovery.rojo_vs_amarrado') IS DISTINCT FROM $v$El semáforo se mide como cliente, no como persona. ROJO: hoy no puede o no quiere comprar —grosero o encantador; puede ser verde como persona y rojo como cliente—: se corta rápido y bien y se va a seguir vendiendo. AMARILLO: está entre el sí y el no —algo se lo impide, o falta valor—: se trabaja, hasta el segundo «no» seguido. VERDE: se nota que quiere comprar. LA PRUEBA: ¿el vendedor averiguó rápido, preguntando, si el cliente puede comprar algo hoy, y actuó según lo que encontró? Si no puede comprar nada, ¿cortó rápido y bien, dejando la puerta abierta? Si algo sí puede, ¿lo trabajó?$v$ THEN RAISE EXCEPTION 'la regla discovery.rojo_vs_amarrado no quedó'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.reglas r WHERE r.id = 'discovery.rojo_vs_amarrado' AND EXISTS (SELECT 1 FROM public.doctrina d WHERE d.is_active AND strpos(d.body, r.cita_cerebro) > 0)) THEN RAISE EXCEPTION 'la cita de discovery.rojo_vs_amarrado no está en el Cerebro'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'discovery.solo_cerradas') IS DISTINCT FROM $v$En la capa 3 el dolor se abre con preguntas abiertas: «¿qué pasa cuando se tarda?», «cuénteme, ¿cómo le hace?». LA PRUEBA: después de que apareció la pista, ¿todas las preguntas del vendedor sobre ella fueron de sí o no, y el cliente dejó de contar? Entonces falla. Una pregunta de sí o no suelta no es esto.$v$ THEN RAISE EXCEPTION 'la regla discovery.solo_cerradas no quedó'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.reglas r WHERE r.id = 'discovery.solo_cerradas' AND EXISTS (SELECT 1 FROM public.doctrina d WHERE d.is_active AND strpos(d.body, r.cita_cerebro) > 0)) THEN RAISE EXCEPTION 'la cita de discovery.solo_cerradas no está en el Cerebro'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'discovery.suelta_amarrado') IS DISTINCT FROM $v$Soltar a un amarillo: rendirse ante quien está entre el sí y el no. Es la falla más cara del oficio: ese cliente sí te iba a comprar y te fuiste solo. LA PRUEBA: cuando el cliente dijo que no puede, ¿el vendedor se fue sin averiguar si algo sí puede comprar hoy? O, si había algo, ¿se rindió antes del segundo «no» seguido? Si averiguó y no quedaba nada, irse es lo correcto.$v$ THEN RAISE EXCEPTION 'la regla discovery.suelta_amarrado no quedó'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.reglas r WHERE r.id = 'discovery.suelta_amarrado' AND EXISTS (SELECT 1 FROM public.doctrina d WHERE d.is_active AND strpos(d.body, r.cita_cerebro) > 0)) THEN RAISE EXCEPTION 'la cita de discovery.suelta_amarrado no está en el Cerebro'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'discovery.suggestive_language') IS DISTINCT FROM $v$Después de preguntar, sugerir tres o cuatro opciones reales del giro del cliente: le das de dónde agarrarse. O elige una, o te corrige con el dato real. LA PRUEBA: cuando el cliente contestó vago o no tenía el dato a la mano, ¿el vendedor le dio opciones concretas (familias, rangos de precio) para que eligiera o lo corrigiera? Si el cliente lo corrige, ¿aceptó la corrección? Si el cliente nunca contestó vago, no hacía falta. Dar opciones no es interrogatorio.$v$ THEN RAISE EXCEPTION 'la regla discovery.suggestive_language no quedó'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.reglas r WHERE r.id = 'discovery.suggestive_language' AND EXISTS (SELECT 1 FROM public.doctrina d WHERE d.is_active AND strpos(d.body, r.cita_cerebro) > 0)) THEN RAISE EXCEPTION 'la cita de discovery.suggestive_language no está en el Cerebro'; END IF;
  IF (SELECT resumen FROM public.reglas WHERE id = 'discovery.escucha') IS DISTINCT FROM $v$Tu siguiente pregunta nace de lo que él dijo. Cuando el cliente te cuenta algo, pregúntale sobre eso, con sus palabras, en vez de sacar la siguiente pregunta de tu lista. Así se siente una plática y no una entrevista. LA PRUEBA: ¿al menos una pregunta del vendedor nace de lo que el cliente acaba de decir, retomando sus palabras o su tema? No se pide recoger todo lo que el cliente menciona: eso sería un interrogatorio.$v$ THEN RAISE EXCEPTION 'la regla discovery.escucha no quedó'; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.reglas r WHERE r.id = 'discovery.escucha' AND EXISTS (SELECT 1 FROM public.doctrina d WHERE d.is_active AND strpos(d.body, r.cita_cerebro) > 0)) THEN RAISE EXCEPTION 'la cita de discovery.escucha no está en el Cerebro'; END IF;
  IF (SELECT regla_id FROM public.skills WHERE id = 'discovery.escucha_activa') IS DISTINCT FROM $v$discovery.escucha$v$ THEN RAISE EXCEPTION 'la habilidad discovery.escucha_activa no quedó'; END IF;
  IF (SELECT regla_id FROM public.skills WHERE id = 'discovery.dolor_real') IS DISTINCT FROM $v$discovery.escalera_capas$v$ THEN RAISE EXCEPTION 'la habilidad discovery.dolor_real no quedó'; END IF;
  IF (SELECT short_description FROM public.skills WHERE id = 'qualification.luz_verde') IS DISTINCT FROM $v$Clasifica al cliente en vivo, como cliente y no como persona: verde (se nota que quiere comprar), amarillo (está entre el sí y el no — ahí vive el trabajo), rojo (hoy no puede o no quiere comprar, aunque sea amable — cortar rápido y bien).$v$ THEN RAISE EXCEPTION 'la habilidad qualification.luz_verde no quedó'; END IF;
