  IF (SELECT md5(practice_script::text) FROM public.nodes WHERE id = '7.3') IS DISTINCT FROM '8f30e19b2f8b3deb42792363becfbf0d' THEN RAISE EXCEPTION 'el guion del 7.3 no quedó'; END IF;
